(function executeRule(current, previous) {
    // === SET THESE EXACTLY TO YOUR INSTANCE ===
    var HEADER_TABLE = 'x_1797098_pettyc_0_pettycashmain';
    var LINES_TABLE = 'x_1797098_pettyc_0_petty_cash_lines'; // <-- use your actual lines table name from the error
    var REF_TO_HEADER = 'pettycashmain_ref'; // header reference field on lines
    var LINE_AMOUNT_FIELD = 'total_line_amount'; // amount on lines
    var HEADER_TOTAL_FIELD = 'total_line_amount'; // total on header
    var PFX = '[PettyCash SUM] ';

    // Collect affected header ids
    var headers = {};
    if (current.operation() !== 'delete') {
        var curHdr = current.getValue(REF_TO_HEADER);
        if (curHdr) headers[curHdr] = true;
    }
    var prevHdr = previous ? previous.getValue(REF_TO_HEADER) : '';
    var refChanged = previous && current.operation() === 'update' &&
        current.getValue(REF_TO_HEADER) !== prevHdr;
    if (current.operation() === 'delete' && prevHdr) headers[prevHdr] = true;
    if (refChanged && prevHdr) headers[prevHdr] = true;

gs.debug(DEBUG_PREFIX + 'op=' + current.operation() +
            ' line=' + current.getUniqueValue() +
            ' cur.' + LINE_AMOUNT_FIELD + '=' + curAmt +
            ' ref=' + (current.getValue(REF_TO_HEADER) || '(none)'));

    function recalc(headerId) {
        if (!headerId) return;

        var ln = new GlideRecord(LINES_TABLE);
        if (!ln.isValid()) {
            gs.error(PFX + 'Lines table not valid: ' + LINES_TABLE);
            return;
        }
        if (!ln.isValidField(REF_TO_HEADER)) {
            gs.error(PFX + 'Invalid REF_TO_HEADER "' + REF_TO_HEADER + '" on ' + LINES_TABLE);
            return;
        }
        if (!ln.isValidField(LINE_AMOUNT_FIELD)) {
            gs.error(PFX + 'Invalid LINE_AMOUNT_FIELD "' + LINE_AMOUNT_FIELD + '" on ' + LINES_TABLE);
            return;
        }

        var total = 0;
        ln.addQuery(REF_TO_HEADER, headerId);
        ln.query();
        while (ln.next()) {
            var v = ln.getValue(LINE_AMOUNT_FIELD);
            var n = parseFloat(v);
            if (!isNaN(n)) total += n;
        }

        var hdr = new GlideRecord(HEADER_TABLE);
        if (hdr.get(headerId)) {
            hdr.setWorkflow(false);
            hdr.setValue(HEADER_TOTAL_FIELD, total);
            hdr.update();
            gs.info(PFX + 'Updated header ' + hdr.getDisplayValue('number') + ' total=' + total);
        } else {
            gs.error(PFX + 'Header not found: ' + headerId);
        }
    }

    for (var id in headers)
        if (headers[id]) recalc(id);
})(current, previous);

